   55|     Lexer(final CSVFormat format, final ExtendedBufferedReader reader) {
   56|         this.reader = reader;
   57|         this.delimiter = format.getDelimiterCharArray();
   58|         this.escape = nullToDisabled(format.getEscapeCharacter());
   59|         this.quoteChar = nullToDisabled(format.getQuoteCharacter());
   60|         this.commentStart = nullToDisabled(format.getCommentMarker());
   61|         this.ignoreSurroundingSpaces = format.getIgnoreSurroundingSpaces();
   62|         this.ignoreEmptyLines = format.getIgnoreEmptyLines();
   63|         this.lenientEof = format.getLenientEof();
   64|         this.trailingData = format.getTrailingData();
   65|         this.delimiterBuf = new char[delimiter.length - 1];
   66|         this.escapeDelimiterBuf = new char[2 * delimiter.length - 1];
   67|     }
