   69|     /**
   70|      * Appends the next escaped character to the token's content.
   71|      *
   72|      * @param token The current token.
   73|      * @throws IOException  on stream access error.
   74|      * @throws CSVException Thrown on invalid input.
   75|      */
   76|     private void appendNextEscapedCharacterToToken(final Token token) throws IOException {
   77|         if (isEscapeDelimiter()) {
   78|             token.content.append(delimiter);
   79|             token.isEscaped = true;
   80|         } else {
   81|             final int unescaped = readEscape();
   82|             if (unescaped == EOF) { // unexpected char after escape
   83|                 // The escape character is kept verbatim, so nothing was translated.
   84|                 token.content.append((char) escape).append((char) reader.getLastChar());
   85|             } else {
   86|                 token.content.append((char) unescaped);
   87|                 token.isEscaped = true;
   88|             }
   89|         }
   90|     }
