  142|     /**
  143|      * Tests whether the next characters constitute a delimiter through {@link ExtendedBufferedReader#peek(char[])}.
  144|      *
  145|      * @param ch
  146|      *             the current character.
  147|      * @return true if the next characters constitute a delimiter.
  148|      * @throws IOException If an I/O error occurs.
  149|      */
  150|     boolean isDelimiter(final int ch) throws IOException {
  151|         isLastTokenDelimiter = false;
  152|         if (ch != delimiter[0]) {
  153|             return false;
  154|         }
  155|         if (delimiter.length == 1) {
  156|             isLastTokenDelimiter = true;
  157|             return true;
  158|         }
  159|         Arrays.fill(delimiterBuf, '\0');
  160|         reader.peek(delimiterBuf);
  161|         for (int i = 0; i < delimiterBuf.length; i++) {
  162|             if (delimiterBuf[i] != delimiter[i + 1]) {
  163|                 return false;
  164|             }
  165|         }
  166|         final int count = reader.read(delimiterBuf, 0, delimiterBuf.length);
  167|         isLastTokenDelimiter = count != EOF;
  168|         return isLastTokenDelimiter;
  169|     }
  170| 
  171|     /**
  172|      * Tests whether the given character occurs in the delimiter.
  173|      *
  174|      * @param ch the character to test.
  175|      * @return true if the given character occurs in the delimiter.
  176|      */
  177|     private boolean isDelimiterChar(final int ch) {
  178|         for (final char delimiterChar : delimiter) {
  179|             if (ch == delimiterChar) {
  180|                 return true;
  181|             }
  182|         }
  183|         return false;
  184|     }
  185| 
  186|     /**
  187|      * Tests if the given character indicates the end of the file.
  188|      *
  189|      * @return true if the given character indicates the end of the file.
  190|      */
  191|     boolean isEndOfFile(final int ch) {
  192|         return ch == EOF;
  193|     }
  194| 
  195|     /**
  196|      * Tests if the given character is the escape character.
  197|      *
  198|      * @return true if the given character is the escape character.
  199|      */
  200|     boolean isEscape(final int ch) {
  201|         return ch == escape;
  202|     }
  203| 
  204|     /**
  205|      * Tests if the next characters constitute a escape delimiter through {@link ExtendedBufferedReader#peek(char[])}.
  206|      *
  207|      * For example, for delimiter "[|]" and escape '!', return true if the next characters constitute "![!|!]".
  208|      *
  209|      * @return true if the next characters constitute an escape delimiter.
  210|      * @throws IOException If an I/O error occurs.
  211|      */
  212|     boolean isEscapeDelimiter() throws IOException {
  213|         Arrays.fill(escapeDelimiterBuf, '\0');
  214|         reader.peek(escapeDelimiterBuf);
  215|         if (escapeDelimiterBuf[0] != delimiter[0]) {
  216|             return false;
  217|         }
  218|         for (int i = 1; i < delimiter.length; i++) {
  219|             if (escapeDelimiterBuf[2 * i] != delimiter[i] || escapeDelimiterBuf[2 * i - 1] != escape) {
  220|                 return false;
  221|             }
  222|         }
  223|         final int count = reader.read(escapeDelimiterBuf, 0, escapeDelimiterBuf.length);
  224|         return count != EOF;
  225|     }
