  227|     private boolean isMetaChar(final int ch) {
  228|         return ch == escape || ch == quoteChar || ch == commentStart;
  229|     }
  230| 
  231|     boolean isQuoteChar(final int ch) {
  232|         return ch == quoteChar;
  233|     }
