  235|     /**
  236|      * Tests if the current character represents the start of a line: a CR, LF, or is at the start of the file.
  237|      *
  238|      * @param ch The character to check.
  239|      * @return true if the character is at the start of a line.
  240|      */
  241|     boolean isStartOfLine(final int ch) {
  242|         return ch == Constants.LF || ch == Constants.CR || ch == Constants.UNDEFINED;
  243|     }
