  245|     /**
  246|      * Returns the next token.
  247|      * <p>
  248|      * A token corresponds to a term, a record change or an end-of-file indicator.
  249|      * </p>
  250|      *
  251|      * @param token An existing Token object to reuse. The caller is responsible for initializing the Token.
  252|      * @return The next token found.
  253|      * @throws IOException  on stream access error.
  254|      * @throws CSVException Thrown on invalid input.
  255|      */
  256|     Token nextToken(final Token token) throws IOException {
  257|         // Get the last read char (required for empty line detection)
  258|         int lastChar = reader.getLastChar();
  259|         // read the next char and set eol
  260|         int c = reader.read();
  261|         // Note: The following call will swallow LF if c == CR. But we don't need to know if the last char was CR or LF - they are equivalent here.
  262|         boolean eol = readEndOfLine(c);
  263|         // empty line detection: eol AND (last char was EOL or beginning)
  264|         if (ignoreEmptyLines) {
  265|             while (eol && isStartOfLine(lastChar)) {
  266|                 // Go on char ahead ...
  267|                 lastChar = c;
  268|                 c = reader.read();
  269|                 eol = readEndOfLine(c);
  270|                 // reached the end of the file without any content (empty line at the end)
  271|                 if (isEndOfFile(c)) {
  272|                     token.type = Token.Type.EOF;
  273|                     // don't set token.isReady here because no content
  274|                     return token;
  275|                 }
  276|             }
  277|         }
  278|         // Did we reach EOF during the last iteration already? EOF
  279|         if (isEndOfFile(lastChar) || !isLastTokenDelimiter && isEndOfFile(c)) {
  280|             token.type = Token.Type.EOF;
  281|             // don't set token.isReady here because no content
  282|             return token;
  283|         }
  284|         if (isStartOfLine(lastChar) && isCommentStart(c)) {
  285|             final String line = reader.readLine();
  286|             if (line == null) {
  287|                 token.type = Token.Type.EOF;
  288|                 // don't set token.isReady here because no content
  289|                 return token;
  290|             }
  291|             final String comment = line.trim();
  292|             token.content.append(comment);
  293|             token.type = Token.Type.COMMENT;
  294|             return token;
  295|         }
  296|         // Important: make sure a new char gets consumed in each iteration
  297|         while (token.type == Token.Type.INVALID) {
  298|             // isDelimiter consumes the trailing characters of a multi-character delimiter as a side effect, so it must
  299|             // only be evaluated once per character. Remember a match found while skipping whitespace below.
  300|             boolean delimiter = false;
  301|             // ignore whitespaces at beginning of a token
  302|             if (ignoreSurroundingSpaces) {
  303|                 while (Character.isWhitespace((char) c) && !eol) {
  304|                     if (isDelimiter(c)) {
  305|                         delimiter = true;
  306|                         break;
  307|                     }
  308|                     c = reader.read();
  309|                     eol = readEndOfLine(c);
  310|                 }
  311|             }
  312|             // ok, start of token reached: encapsulated, or token
  313|             if (delimiter || isDelimiter(c)) {
  314|                 // empty token return TOKEN("")
  315|                 token.type = Token.Type.TOKEN;
  316|             } else if (eol) {
  317|                 // empty token return EORECORD("")
  318|                 // noop: token.content.append("");
  319|                 token.type = Token.Type.EORECORD;
  320|             } else if (isQuoteChar(c)) {
  321|                 // consume encapsulated token
  322|                 parseEncapsulatedToken(token);
  323|             } else if (isEndOfFile(c)) {
  324|                 // end of file return EOF()
  325|                 // noop: token.content.append("");
  326|                 token.type = Token.Type.EOF;
  327|                 token.isReady = true; // there is data at EOF
  328|             } else {
  329|                 // next token must be a simple token
  330|                 // add removed blanks when not ignoring whitespace chars...
  331|                 parseSimpleToken(token, c);
  332|             }
  333|         }
  334|         return token;
  335|     }
  336| 
  337|     private int nullToDisabled(final Character c) {
  338|         return c == null ? Constants.UNDEFINED : c.charValue(); // Explicit unboxing
  339|     }
