  341|     /**
  342|      * Parses an encapsulated token.
  343|      * <p>
  344|      * Encapsulated tokens are surrounded by the given encapsulating string. The encapsulator itself might be included
  345|      * in the token using a doubling syntax (as "", '') or using escaping (as in \", \'). Whitespaces before and after
  346|      * an encapsulated token is ignored. The token is finished when one of the following conditions becomes true:
  347|      * </p>
  348|      * <ul>
  349|      * <li>An unescaped encapsulator has been reached and is followed by optional whitespace then:</li>
  350|      * <ul>
  351|      * <li>delimiter (TOKEN)</li>
  352|      * <li>end of line (EORECORD)</li>
  353|      * </ul>
  354|      * <li>end of stream has been reached (EOF)</li> </ul>
  355|      *
  356|      * @param token
  357|      *            the current token
  358|      * @return A valid token object
  359|      * @throws IOException
  360|      *             Thrown when in an invalid state: EOF before closing encapsulator or invalid character before
  361|      *             delimiter or EOL.
  362|      * @throws CSVException Thrown on invalid input.
  363|      */
  364|     private Token parseEncapsulatedToken(final Token token) throws IOException {
  365|         token.isQuoted = true;
  366|         // Save current line number in case needed for IOE
  367|         final long startLineNumber = getCurrentLineNumber();
  368|         int c;
  369|         while (true) {
  370|             c = reader.read();
  371|             if (isQuoteChar(c)) {
  372|                 if (isQuoteChar(reader.peek())) {
  373|                     // double or escaped encapsulator -> add single encapsulator to token
  374|                     c = reader.read();
  375|                     token.content.append((char) c);
  376|                 } else {
  377|                     // token finish mark (encapsulator) reached: ignore whitespace till delimiter
  378|                     while (true) {
  379|                         c = reader.read();
  380|                         if (isDelimiter(c)) {
  381|                             token.type = Token.Type.TOKEN;
  382|                             return token;
  383|                         }
  384|                         if (isEndOfFile(c)) {
  385|                             token.type = Token.Type.EOF;
  386|                             token.isReady = true; // There is data at EOF
  387|                             return token;
  388|                         }
  389|                         if (readEndOfLine(c)) {
  390|                             token.type = Token.Type.EORECORD;
  391|                             return token;
  392|                         }
  393|                         if (trailingData) {
  394|                             token.content.append((char) c);
  395|                         } else if (!Character.isWhitespace((char) c)) {
  396|                             // error invalid char between token and next delimiter
  397|                             throw new CSVException("Invalid character between encapsulated token and delimiter at line: %,d, position: %,d",
  398|                                     getCurrentLineNumber(), getCharacterPosition());
  399|                         }
  400|                     }
  401|                 }
  402|             } else if (isEscape(c)) {
  403|                 appendNextEscapedCharacterToToken(token);
  404|             } else if (isEndOfFile(c)) {
  405|                 if (lenientEof) {
  406|                     token.type = Token.Type.EOF;
  407|                     token.isReady = true; // There is data at EOF
  408|                     return token;
  409|                 }
  410|                 // error condition (end of file before end of token)
  411|                 throw new CSVException("(startline %,d) EOF reached before encapsulated token finished", startLineNumber);
  412|             } else {
  413|                 // consume character
  414|                 token.content.append((char) c);
  415|             }
  416|         }
  417|     }
