  419|     /**
  420|      * Parses a simple token.
  421|      * <p>
  422|      * Simple tokens are tokens that are not surrounded by encapsulators. A simple token might contain escaped delimiters (as \, or \;). The token is finished
  423|      * when one of the following conditions becomes true:
  424|      * </p>
  425|      * <ul>
  426|      * <li>The end of line has been reached (EORECORD)</li>
  427|      * <li>The end of stream has been reached (EOF)</li>
  428|      * <li>An unescaped delimiter has been reached (TOKEN)</li>
  429|      * </ul>
  430|      *
  431|      * @param token The current token.
  432|      * @param ch     The current character.
  433|      * @return The filled token.
  434|      * @throws IOException  on stream access error.
  435|      * @throws CSVException Thrown on invalid input.
  436|      */
  437|     private Token parseSimpleToken(final Token token, final int ch) throws IOException {
  438|         // Faster to use while(true)+break than while(token.type == INVALID)
  439|         int cur = ch;
  440|         while (true) {
  441|             if (readEndOfLine(cur)) {
  442|                 token.type = Token.Type.EORECORD;
  443|                 break;
  444|             }
  445|             if (isEndOfFile(cur)) {
  446|                 token.type = Token.Type.EOF;
  447|                 token.isReady = true; // There is data at EOF
  448|                 break;
  449|             }
  450|             if (isDelimiter(cur)) {
  451|                 token.type = Token.Type.TOKEN;
  452|                 break;
  453|             }
  454|             // continue
  455|             if (isEscape(cur)) {
  456|                 appendNextEscapedCharacterToToken(token);
  457|             } else {
  458|                 token.content.append((char) cur);
  459|             }
  460|             cur = reader.read(); // continue
  461|         }
  462| 
  463|         if (ignoreSurroundingSpaces) {
  464|             trimTrailingSpaces(token.content);
  465|         }
  466| 
  467|         return token;
  468|     }
  469| 
  470|     /**
  471|      * Greedily accepts \n, \r and \r\n This checker consumes silently the second control-character...
  472|      *
  473|      * @return true if the given or next character is a line-terminator.
  474|      */
  475|     boolean readEndOfLine(final int ch) throws IOException {
  476|         // check if we have \r\n...
  477|         int cur = ch;
  478|         if (cur == Constants.CR && reader.peek() == Constants.LF) {
  479|             // note: does not change ch outside of this method!
  480|             cur = reader.read();
  481|             // Save the EOL state
  482|             if (firstEol == null) {
  483|                 this.firstEol = Constants.CRLF;
  484|             }
  485|         }
  486|         // save EOL state here.
  487|         if (firstEol == null) {
  488|             if (cur == Constants.LF) {
  489|                 this.firstEol = LF_STRING;
  490|             } else if (cur == Constants.CR) {
  491|                 this.firstEol = CR_STRING;
  492|             }
  493|         }
  494| 
  495|         return cur == Constants.LF || cur == Constants.CR;
  496|     }
  497| 
  498|     // TODO escape handling needs more work
  499|     /**
  500|      * Handle an escape sequence. The current character must be the escape character. On return, the next character is available by calling
  501|      * {@link ExtendedBufferedReader#getLastChar()} on the input stream.
  502|      *
  503|      * @return The unescaped character (as an int) or {@link IOUtils#EOF} if char following the escape is invalid.
  504|      * @throws IOException  if there is a problem reading the stream or the end of stream is detected: the escape character is not allowed at end of stream
  505|      * @throws CSVException Thrown on invalid input.
  506|      */
  507|     int readEscape() throws IOException {
  508|         // the escape char has just been read (normally a backslash)
  509|         final int ch = reader.read();
  510|         switch (ch) {
  511|         case 'r':
  512|             return Constants.CR;
  513|         case 'n':
  514|             return Constants.LF;
  515|         case 't':
  516|             return Constants.TAB;
  517|         case 'b':
  518|             return Constants.BACKSPACE;
  519|         case 'f':
  520|             return Constants.FF;
  521|         case Constants.CR:
  522|         case Constants.LF:
  523|         case Constants.FF: // TODO is this correct?
  524|         case Constants.TAB: // TODO is this correct? Do tabs need to be escaped?
  525|         case Constants.BACKSPACE: // TODO is this correct?
  526|             return ch;
  527|         case EOF:
  528|             throw new CSVException("EOF while processing escape sequence");
  529|         default:
  530|             // 1) Now check for meta-characters
  531|             // 2) An escaped delimiter character unescapes to the bare character: the printer escapes each character of
  532|             //    a multi-character delimiter individually, including a straddling prefix of the delimiter at the end of
  533|             //    an unquoted value. A fully escaped delimiter never reaches this method: isEscapeDelimiter() consumes it
  534|             //    first.
  535|             if (isMetaChar(ch) || isDelimiterChar(ch)) {
  536|                 return ch;
  537|             }
  538|             // indicate unexpected char - available from in.getLastChar()
  539|             return EOF;
  540|         }
  541|     }
