  543|     void trimTrailingSpaces(final StringBuilder buffer) {
  544|         int length = buffer.length();
  545|         while (length > 0 && Character.isWhitespace(buffer.charAt(length - 1))) {
  546|             length--;
  547|         }
  548|         if (length != buffer.length()) {
  549|             buffer.setLength(length);
  550|         }
  551|     }
  552| }
